// Generated by tools/dzc/build_scenario_terms.py from data/dzc/rules-wiki.json. Verbatim; do not edit by hand.
const DZ_TERMS={"territory": ["Territories are where each player’s Groups begin the game or enter the Table from. If the Territory includes a Table Edge/s, Groups enter from those Edges. If it does not, Groups enter from any point within it.", "A player’s Table Edge ends at the edge of their Territory if it does not cover the whole side of the Table. A Territory may be just a Table Edge / a portion of one/s."], "entry": {"Deployed": ["These Groups begin on the Table within their Territory. Before the game’s first Initiation Phase, each player rolls a D6, and the lowest scoring places one of these Groups. Alternate until all these Groups are placed.", "Infantry may Deploy inside a Zone which touches this Territory. Units may be Deployed outside of their Transports, but only within 3” of them."], "Ready": ["These Groups begin off the Table and may enter when activated."], "Reserved": ["These Groups begin off the Table and become Ready from Round 2."], "Holding": ["These Groups may only enter when and where a rule allows them to, often not from their Territory. Units in Holding at the end of the game count as destroyed."]}, "objectives": {"Attrition": {"heading": "Attrition X", "body": ["Players are awarded X VP at the end of the game for every 200 KP they have scored."]}, "Extract": {"heading": "Extract X/Y", "body": ["Players are awarded X VP for Extracting certain Objects (see page 36 ‘Objects’). Otherwise, Y VP are awarded at the end of the game for Objects you Carry but have not Extracted."]}, "Displace": {"heading": "Displace X", "body": ["Players gain X VP at the end of the game for every 200pts of Vehicles they have within regions indicated by the Scenario."]}, "Dominate": {"heading": "Dominate X/Y", "body": ["Players with 200pts or more of Vehicles within certain Table segments Challenge for Y VP per segment. Or, players with the most points of Vehicles within those segments, and only if they have 200pts or more there, Dominate for X VP per segment.", "Since a Unit’s centre is infinitely small, it can’t be in two segments."]}, "Explore": {"heading": "Explore X", "body": ["When a Squad completes a full activation Occupying certain Zones—it must begin and end its activation inside—its player gains X VP. Each Zone may only yield VP in this way once per player per game."]}, "Occupy": {"heading": "Occupy X/Y", "body": ["Players are awarded X VP for Controlling certain Zones, or Y VP for Contesting them. If the Zone is destroyed, players no longer score for that Zone."]}, "Protect": {"heading": "Protect X/Y", "body": ["Players are awarded X VP at the end of the game if certain Zones are not Compromised, or Y VP if they are not destroyed. Compromised Zones have half or fewer of their initial DP remaining."]}, "Raze": {"heading": "Raze X/Y", "body": ["Players are awarded X VP when certain Zones are destroyed, or Y VP if they are Compromised at the end of the game. Compromised Zones have half or fewer of their initial DP remaining."]}, "Secure": {"heading": "Secure X/Y", "body": ["Players are awarded VP for having Vehicles within 3” of certain Zones or within 6” of certain points. Players Secure the Zone/point for X VP if only they have Vehicles there, or Challenge instead for Y VP if they have 100pts or more of Vehicles there. If the Zone is destroyed, players no longer score for that Zone."]}}, "objects": {"Objects": ["For the Extract Scenario Objective, the capture and/or extraction of movable Objects is the goal. Objects are represented by tokens—the Scenario will dictate where to place them."], "Finding Objects": ["Objects must be found before they can be interacted with.", "Objects on Ground are found by moving over them with Infantry or a Vehicle.", "Objects inside Zones must be Searched for. When an Occupying Squad begins its Activation, it may Search. Roll 1D6—on a 6+ for Large Zones or a 5+ for other sizes, the Object is found. If no enemy Units Occupy this Zone, Squads gain +1 to this roll. Squads which Searched this Zone in one or more previous Rounds gain +1 to this roll.", "Each player may only Search a Zone up to twice per Round."], "Carrying Objects": ["A Unit that finds an Object may carry it. If it was found inside a Zone, any Unit in the Squad that Searched may carry it.", "Only Infantry and Vehicles, or Aircraft which can directly carry Infantry, may Transport Objects. Aircraft may transport Units carrying Objects.", "Carrying an Object does not require Transport capacity. A Unit may carry multiple Objects."]}, "extraction": {"Friendly Lines": "Squads may leave the Table from any Table Edge within their Territory if carrying an Object, transporting a carrying Unit, or sharing a Transport with one—simply move them off the Table. They become Ready and may return next Round from the same Table Edge.", "Enemy Lines": "This works like Friendly Lines, but the Object must be Extracted from a Table Edge within the opponent’s Territory.", "Extraction Point": "One or more points are specified for each player. Each Carried Object that player has within 3” of one of their points at the end of the game is Extracted.", "Hold": "You cannot extract these Objects."}, "variantObjects": {"Data Download": ["Once found, this Object is worth 1 additional VP for every Cleanup Phase it spends inside the Zone in which it was found."], "Remaining Intel": ["At the end of the Round in which this Object was removed from the Zone it started in, place another un-found Object with Remaining Intel in that Zone. Squads lose any +1 Search bonuses for having previously searched that Zone."]}, "weaponFeatures": {"rules": ["Each Weapon in the following table corresponds to a Feature with the same name. A Zone may have duplicates of the same Weapon Feature.", "In the Fire Weapon Features step of the Activation Phase, the player with the Initiative picks a Zone they Control with Weapons Features, activates it, and attacks with it like a Squad. Next, their opponent picks one of theirs, and so on until all Zones with Weapons Features have been activated.", "Range and Line of Sight for each Weapon may together be measured from any point on a Building or any edge point on an Area."], "weapons": {"Railgun Turret": {"arc": "F/S/R", "range": "∞/24”", "attacks": "2", "accuracy": "2+", "energy": "6", "special": "Demo 1"}, "Missile Turret": {"arc": "F/S/R", "range": "48/9”", "attacks": "6", "accuracy": "2+", "energy": "4", "special": "Strafe"}, "Laser Turret": {"arc": "F/S/R", "range": "∞", "attacks": "D3", "accuracy": "2+", "energy": "5", "special": "-"}, "Flak Turret": {"arc": "F/S/R", "range": "36/18”", "attacks": "6", "accuracy": "3+", "energy": "2", "special": "AA-S"}, "Heavy Cannon Turret": {"arc": "F/S/R", "range": "∞/24”", "attacks": "2", "accuracy": "3+", "energy": "9", "special": "Demo 2"}, "Superlaser Turret": {"arc": "F/S/R", "range": "∞", "attacks": "1", "accuracy": "4+", "energy": "10", "special": "Destroyer 5+, Demo 5"}}}, "features": {"ACM Package": {"kind": "effect", "text": "Weapons with two R values that target this Zone or its Occupiers must use their 2nd value."}, "Automated Sentries": {"kind": "effect", "text": "Each Infantry Squad entering this Zone takes 2D6 Small Arms hits before entering. Once a player Controls this Zone, only enemy Infantry are hit."}, "Comms Uplink": {"kind": "effect", "text": "This Zone’s Controller generates an additional CP in the Planning Phase."}, "Jamming Device": {"kind": "effect", "text": "Units within 8” of this Zone that are enemies of this Zone’s Controller gain UC and cannot benefit from Aegis."}, "Power Core": {"kind": "effect", "text": "If this Feature is destroyed, this Zone takes 3D6 damage. This damage may not be converted into destroying another Feature. If this Zone is destroyed by this or destroyed with this Feature, Units are potentially damaged within 4” rather than the usual 2”."}, "Seal": {"kind": "effect", "text": "This Zone can’t be entered through any of its faces or edges."}, "Shield Generator": {"kind": "effect", "text": "This Zone gains 4+ Passive countermeasures."}, "Shimmer Field": {"kind": "effect", "text": "Weapons can never hit this Zone or its Occupiers on a better roll than 4+ instead of always hitting it on a 2+. This cannot be modified, even by special rules. Weapons with an Ac value of A hit this Zone automatically."}, "Basement": {"kind": "indestructible", "text": "Squads may be Sited in the basement. Squads Sited in the basement cannot attack or be attacked, even by Weapons with Flame or Seeker. They have DF2+ against Collateral Damage hits and suffer -1 to Search rolls (see page 36 ‘Objects’)."}, "Excellent Vantage": {"kind": "indestructible", "text": "When attacking from this Zone, Infantry Weapons gain +1E and +6” to their R value/s. Their Small Arms Weapons may attack aircraft within 12” rather than 9”."}, "Internal Flaw": {"kind": "indestructible", "text": "A Controlling player whose Squad begins its activation Occupying this Zone may instantly destroy it at the end of any friendly activation, providing none of their Squads still Occupy it. If their opponent becomes the Controller, the player loses this ability."}, "Secret Entrance": {"kind": "indestructible", "text": "This Feature comes in pairs, placed on one Zone and one point on the Table. Infantry may enter that Zone from this point. Squads cannot be Sited on that point."}, "Underground Monorail": {"kind": "indestructible", "text": "This Feature comes in pairs, placed on two Zones. Infantry may transfer between those Zones as if they were touching."}}, "featureRules": {"Zones - Features": ["Features are distinct elements of a Zone with special rules. Scenarios will specify which to use. Features are represented by tokens or removable parts since they can be destroyed.", "For every 5 damage a Zone takes during a single activation, the active player may remove one Feature from that Zone instead of inflicting 5DP. Collateral Damage is still inflicted."], "Indestructible Features": ["These Features cannot be destroyed. Remove them if their Zone is destroyed."]}, "bunkerEntrances": ["These are special Zones where only a small part is visible on the surface. These cannot be damaged or destroyed. Features placed on Bunker Entrances by Scenarios cannot therefore be destroyed, but they cannot gain Features during games. Only one Squad may be Sited on Bunker Entrances."], "specialRules": {"Aegis": {"heading": "Aegis X”", "number": "10.1.1", "body": ["Friendly Units within X” of this Unit lose UC."]}, "Agile": {"heading": "Agile X", "number": "10.1.2", "body": ["During CQBs, this Unit automatically passes X DF rolls—each Unit in the Squad contributes X. It cannot automatically pass First Strike hits but gains +1DF against them.", "Agile Units gain +1DF against Collateral Damage hits."]}, "AWACS": {"heading": "AWACS X”", "number": "10.1.3", "body": ["Enemy Aircraft within X” of one or more Units with this rule may be attacked with +1Ac bonus."]}, "Bloodthirsty": {"heading": "Bloodthirsty", "number": "10.1.4", "body": ["While Occupying a Zone containing enemies, Bloodthirsty Infantry suffer -2 to Search rolls and may not exit."]}, "Breachers": {"heading": "Breachers X", "number": "10.1.5", "body": ["Breachers may enter a Building from any point on it—they do not require an Entrance. Breachers ignore Sited enemies and the Automated Sentries and Seal Effect Features when entering Zones.", "When a Squad with Breachers enters a Building, select one random enemy Occupying Squad. Each Breaching Unit inflicts X Small Arms hits on that Squad."]}, "Climber": {"heading": "Climber", "number": "10.1.6", "body": ["This Unit may move over any scenery that isn’t Impassable Ground."]}, "Command Centre": {"heading": "Command Centre", "number": "10.1.7", "body": ["If this Unit contains a Commander, double the Radius of Command Cards measured from this Unit."]}, "Delayed": {"heading": "Delayed", "number": "10.1.8", "body": ["This Transport cannot Disembark or Embark Units in the same Round that it Disembarks."]}, "Demo Charges": {"heading": "Demo Charges X+", "number": "10.1.9", "body": ["If this Infantry Unit begins its activation inside a Zone, you may place a Demo Charge Token on that Zone. If enemy Occupiers are present, its Squad must pass a Bravery Test first.", "If you have no Occupiers in a Zone containing your Demo Charge Tokens, you may remove them all at the end of any friendly activation—each inflicts 2DP on that Zone on an X+. This suffers -1 if one enemy Occupying Squad is present, or -2 if more than one is present."]}, "Dogs": {"heading": "Dogs", "number": "10.1.10", "body": ["Friendly Squads Occupying the same Zone as one or more friendly Dogs Units gain +1 to Search rolls.", "During step 3 of CQBs, players must allocate at least 1 hit to each enemy Squad with Dogs per remaining DP that Squad has before allocating any to other Squads.", "Dogs with Living Weapons may Embark into Transports."]}, "Ev": {"heading": "Ev X (Evasion)", "number": "10.1.11", "body": ["Weapons attacking targets with Ev suffer -X Ac. Ev is ignored when targeting friendly Units."]}, "Fast Mover": {"heading": "Fast Mover", "number": "10.1.12", "body": ["Fast Movers are Aircraft with two Mv stats—a minimum and maximum. They must move at least their minimum Mv each activation, in a straight line, and before attacking. They may move less than their minimum Mv when entering the Table. They may pivot up to 45 degrees at the beginning of their move and again at its end. Units within a Fast Mover Squad must end their move parallel to each other, facing the same way.", "Fast Movers can always move off the Table. If any Unit in the Squad moves off, the Squad leaves the Table. They then return to Ready.", "Fast Movers ALWAYS begin the game Reserved.", "Fast Movers are ignored for determining Victory Points but do concede Kill Points.", "Commanders may not be assigned to Fast Movers."]}, "Flying High": {"heading": "Flying High", "number": "10.1.12.1", "body": ["A Fast Mover Squad can elect to fly high at the end of its move, before pivoting– indicate this with a token. High-fliers can pivot up to 180 degrees. High-fliers can only target and be targeted by other Fast Movers flying high. Nothing blocks Line of Sight to high-fliers.", "A high-flier can end its move in illegitimate places, including over Zones - remove it from its flight stand/substitute a token for it if it can’t stand up.", "The Squad remains flying high until it leaves the Table or elects to return to normal height. It may do this at the end of its move, before pivoting."]}, "Flat Out": {"heading": "Flat Out X”", "number": "10.1.13", "body": ["If this Unit does not Embark, Disembark, or attack in an activation, it gains +X” Mv."]}, "FS": {"heading": "FS X(First Strike)", "number": "10.1.14", "body": ["At the start of a CQB, each non-Sited Unit with First Strike inflicts X Small Arms hits on the enemy Squads, distributed freely. If both players have First Strike Units involved, the player without the Initiative distributes their hits first. DF saves are then attempted simultaneously."]}, "Hardy": {"heading": "Hardy X", "number": "10.1.15", "body": ["Instead of using its DF, even if it would not normally be able to, this Infantry Unit may use a save of X+ against hits from Weapons, Collateral Damage, and Command Cards. Hits from anything above E2 ignore this rule."]}, "Infiltrate": {"heading": "Infiltrate X”", "number": "10.1.16", "body": ["This Unit may always Deploy up to X” from their Territory. Infiltrating Infantry", "may Deploy as Occupiers in a Zone, but that Zone must be wholly within X” of their Territory.", "Non-Auxiliary Transports of Squads with Infiltrate that choose to Infiltrate must begin Ready—they are allowed to start empty. Otherwise, Units cannot Infiltrate if part of a Group containing Units without Infiltrate.", "A Transport with Infiltrate confers Infiltrate to all Units aboard."]}, "Jump": {"heading": "Jump X”", "number": "10.1.17", "body": ["If it does not Embark or Disembark from a Unit that activation, this Unit may Jump when it starts moving—during its move, but not at its end, it is an Aircraft with an X” Mv. If Embarking/Disembarking from a Zone, this Mv is not halved.", "If an AA Weapon Reaction Attacks it, this Unit suffers -3A for that attack. Line of Sight is measured to a point 2” above the Jumper. Jump Infantry are still damaged as Infantry."]}, "Large": {"heading": "Large", "number": "10.1.18", "body": ["Large Vehicles cannot be Obscured except by Obscured Status Tokens granted by Stealth—otherwise, if Obscured, you have Clear Line of Sight.", "If any part of a Large Vehicle miniature is within 2” of a Building when that Building is destroyed, it takes hits as if its centre was within 2”.", "When attacking with a Large Vehicle’s Weapons, use the Weapon’s pivot point (if it’s on a ball joint or turret) or the base of the barrel (if it’s fixed) to determine range and Line of Sight for that Weapon. Arcs should be drawn from the centre of the model as usual.", "When Embarking or Disembarking into or from a Large Transport, add 2” to the allowed Embark/Disembark distance.", "If the size of a Large Vehicle makes it impossible for a Weapon to get into range against it, physical contact is sufficient."]}, "Lethal": {"heading": "Lethal", "number": "10.1.19", "body": ["CQB dice contributed by this Unit hit automatically."]}, "Living Weapons": {"heading": "Living Weapons", "number": "10.1.20", "body": ["Commanders cannot be assigned to Living Weapons. They may begin the game aboard a Transport but may not Embark into one. They may enter Zones.", "Living Weapons cannot Search for or carry Objects. They cannot exit Zones with enemy Occupiers. A player with only Living Weapon Occupiers can only Contest that Zone.", "Living Weapons with the same name Occupying the same Zone automatically form one Squad/ join an existing Squad of Living Weapons with the same name at the start of the Initiation Phase—their player may choose which Squad they join. This can take the Squad above its maximum Squad size."]}, "Obscurer": {"heading": "Obscurer X”", "number": "10.1.21", "body": ["All friendly Vehicle and Infantry Units within X” of this Unit are Obscured to enemies."]}, "PX+": {"heading": "PX+ (Passive Countermeasures)", "number": "10.1.22", "body": ["This Unit may attempt to block any damage it would receive by rolling 1 D6 for each point of damage—each result of at least X blocks the damage.", "Against damage from E9 sources, after modifiers are applied, Passive Countermeasures suffer a -1 modifier. E10 sources, after modifiers are applied, ignore Passive Countermeasures.", "Once all modifiers are applied, Passive Countermeasures can never exceed 3+.", "Occupiers inside Zones with Passive Countermeasures gain those Passive Countermeasures against damage dealt directly by Weapons."]}, "Rapid Insertion": {"heading": "Rapid Insertion X”", "number": "10.1.23", "body": ["An Aircraft transporting Rapid Insertion Units which have not Embarked this Round may move up to an additional X” after all other modifiers are applied before these Units Disembark. The Aircraft cannot move further than its unmodified Mv using this rule.", "Units with Rapid Insertion may Disembark when their Transport is within 3” of an enemy Vehicle."]}, "Regenerate": {"heading": "Regenerate X", "number": "10.1.24", "body": ["This Unit recovers X lost DP in the Cleanup step of the End Phase."]}, "Resilient": {"heading": "Resilient", "number": "10.1.25", "body": ["Criticals from non-Blast Weapon hits below E9, after modifiers are applied, do not inflict any additional damage against this Unit."]}, "Scanner": {"heading": "Scanner", "number": "10.1.26", "body": ["This Unit gains Clear Line of Sight against targets that would otherwise be Obscured. Other Units in this Unit’s Squad, and other Units in its Group within 4”, also gain Clear Line of Sight against targets that would otherwise be Obscured."]}, "Scout": {"heading": "Scout", "number": "10.1.27", "body": ["You may measure a Command Card’s Radius from friendly Scout Units.", "If a Weapon with Indirect draws Line of Sight from this Unit, the -2Ac penalty is ignored."]}, "Shield": {"heading": "Shield: X Y” Z+", "number": "10.1.28", "body": ["All Units/Zones as defined by X within Y” of this Unit gain Z+ Passive Countermeasures."]}, "Skimmer": {"heading": "Skimmer", "number": "10.1.29", "body": ["Skimmers ignore all types of Ground and may move over protruding Ground details less than 1” high. Skimmers may drop down any incline."]}, "Stealth": {"heading": "Stealth", "number": "10.1.30", "body": ["If it will spend its full activation disembarked, this Squad may choose to only move OR move 0” and attack. If it does, this Squad gains an Obscured Status Token. Squads with Obscured Status Tokens are Obscured."]}, "Strike": {"heading": "Strike", "number": "10.1.31", "body": ["This Unit may always begin the game Ready. Units Disembarking directly from this Unit gain Assault on their Weapons."]}, "Strong": {"heading": "Strong", "number": "10.1.32", "body": ["Per Squad with two or more Strong Units in a CQB, one enemy Squad of your choosing suffers -1DF for that CQB, assigned at the start of step 1 of that CQB. If both players have Strong Units involved, the player without the Initiative chooses an enemy Squad(s) to affect first."]}, "Surveyor": {"heading": "Surveyor", "number": "10.1.33", "body": ["If one or more friendly Units with Surveyor are within 1” of a Zone with friendly Occupiers at the end of the Round, you may place one Mapping Token on that Zone. When Searching for an Objective, you may spend two Mapping Tokens on that Zone to find the Objective on a 2+.", "If you have no friendly Units with Surveyor within 1” of a Zone at the end of any activation (yours or your opponent’s), remove all your Mapping Tokens from it."]}, "Terror": {"heading": "Terror", "number": "10.1.34", "body": ["Enemies Occupying the same Zone as Terror Units suffer -1B and -1 to Search rolls."]}, "UC": {"heading": "UC (Un-countered)", "number": "10.1.35", "body": ["If a Weapon targeting this Unit has two R values, it may always use its first."]}, "Wide": {"heading": "Wide X”", "number": "10.1.36", "body": ["Units in this Squad must maintain a coherency of X” rather than the usual 3”."]}, "AA": {"heading": "AA(Anti-Aircraft)", "number": "11.1.1", "body": ["Only AA Weapons can target Aircraft normally. AA Weapons ignore Ev on non-Aircraft. AA Weapons may Reaction Attack—see main rules."]}, "AA-R": {"heading": "AA-R (Anti-Aircraft- Reactive)", "number": "11.1.1.1", "body": ["This AA Weapon may only Reaction Attack but suffers no penalty for doing so."]}, "AA-S": {"heading": "AA-S (Anti-Aircraft-Slow)", "number": "11.1.1.2", "body": ["This AA Weapon may not Reaction Attack."]}, "ALT": {"heading": "ALT X (Alternate)", "number": "11.1.2", "body": ["Units may only attack with one Weapon with the same ALT number (X) each Round."]}, "Articulated": {"heading": "Articulated", "number": "11.1.3", "body": ["Line of Sight may be measured from a point 1” above the model’s centre when attacking with this Weapon."]}, "Assault": {"heading": "Assault", "number": "11.1.4", "body": ["This Weapon may attack on the same round as Disembarking from a Transport, and/or entering or exiting a Zone. If it does any of these it suffers -2 Ac, or -1 Ac if it has a R of CC. It still may not attack in the same Round as Embarking into a Transport.", "If a Unit with an Assault Weapon Disembarks then moves 0”, it counts as having moved 1” for attacking purposes."]}, "Battery": {"heading": "Battery X", "number": "11.1.5", "body": ["This Weapon gains X E for each other instance of this Weapon in coherency. Only one Battery Weapon with the same name may attack per Squad per Round. If one attacks, each other instance of that Weapon in coherency counts as having attacked."]}, "Blast": {"heading": "Blast", "number": "11.1.6", "body": ["This Weapon uses the Blast Template — a 5” diameter circle. First, place the template’s centre over the target’s centre—this is the primary target. Place all templates from one activation’s attacks simultaneously. All Units and Zones within the template are now targets. Roll to hit once against each target for each template. If the primary target was Obscured, everything under the template is Obscured, otherwise Obscured is ignored. Roll D6 times per template against Infantry.", "If the primary target is a Vehicle with Large or a Zone, do not place the template but roll to hit D3 times. This Weapon can inflict Critical damage against Zones.", "If the primary target is a Sited Squad, do not place the template. Instead, roll to hit the Squad D6 times. Roll to hit the Zone once.", "If the primary target is an Aircraft, only Aircraft under the template and not flying high are targets. If the primary target is a non-Aircraft, aircraft are not targets."]}, "Concussion": {"heading": "Concussion", "number": "11.1.7", "body": ["If a Unit is hit by this Weapon, place a Concussed Status Token on its Squad. Concussed Squads suffer -2Ac. Concussed Infantry also count as Sited in CQBs and do not contribute to Entrances Covered."]}, "Critical": {"heading": "Critical X", "number": "11.1.8", "body": ["This Weapon inflicts X additional DP for each Critical it inflicts against Units."]}, "Demo": {"heading": "Demo X", "number": "11.1.9", "body": ["This Weapon can inflict Critical damage against Zones. It also inflicts X additional DP for each success when rolling to inflict damage against Zones."]}, "Destroyer": {"heading": "Destroyer X+", "number": "11.1.10", "body": ["If this Weapon hits by rolling equal to or", "higher than X, it will automatically cause a Critical instead of rolling to damage. This counts as a successful roll to damage. This Weapon’s Ac cannot be modified below X."]}, "Devastator": {"heading": "Devastator X", "number": "11.1.11", "body": ["This Weapon inflicts X additional DP for each success when rolling to inflict damage against Units."]}, "Dissipate": {"heading": "Dissipate -X", "number": "11.1.12", "body": ["This Weapon may suffer -X E to double its R value/s. It may do this twice to quadruple its R."]}, "Drive-by": {"heading": "Drive-by", "number": "11.1.13", "body": ["This Weapon may measure range and Line of Sight from any point its Unit moved through that activation if it moved in a single straight line. It may pivot before moving."]}, "Field": {"heading": "Field", "number": "11.1.14", "body": ["This Weapon does not target anything. Instead, each Zone, Vehicle, and Infantry Unit within its R are assigned attacks equal to its Att. Instead, each Zone, Vehicle, and Infantry Unit within its R are assigned attacks equal to its Att. Since it does not target anything, Line of Sight is not needed and friendlies may be hit.", "Units within this Weapon’s Squad are not damaged by it and cannot receive Concussed, Jammed, or Suppressed Status Tokens from it.", "If this Weapon has AA, its attacks are assigned to Aircraft instead of Zones, Vehicles, and Infantry.", "If this Weapon places Status Tokens, place one on every Squad within its R that could receive the Token. This counts as placing one of that Token."]}, "Flame": {"heading": "Flame", "number": "11.1.15", "body": ["This Weapon ignores the Ac penalty against Obscured targets, and it ignores Evasion. Infantry suffer -1DF against this Weapon.", "This Weapon may target Occupiers as if they were Sited anywhere on a Zone.", "If friendly Squads are present in this Zone, all misses from your Flame Weapons which targeted enemies in this Zone this activation hit one random friendly Squad in that Zone instead.", "Flame Weapons with Small Arms may also combine their attacks against Zones. This Weapon can inflict Critical damage against Zones. Flame Weapons gain +1 Demo against Areas."]}, "Focus": {"heading": "Focus X", "number": "11.1.16", "body": ["You may discard any number of successful hits from one or more instances of this Weapon to add X E to another remaining hit. For example, two identical E2 Cannons with Focus 1 and 4 attacks each score a total of 6 hits. Their player chooses to discard 4 of these hits to add 2 Energy to each of the remaining hits, resulting in two E4 hits."]}, "GB": {"heading": "GB(Gravity Bomb)", "number": "11.1.17", "body": ["A Weapon with a R value of GB is a Gravity Bomb. It may target anything within 2” of any point its Unit moved over that Round. Line of Sight is checked from that point."]}, "Ignores Cover": {"heading": "Ignores Cover", "number": "11.1.18", "body": ["This Weapon ignores the Ac penalty for Obscured targets. Sited Infantry may not use their DF value to block hits from this Weapon."]}, "Incendiary": {"heading": "Incendiary X", "number": "11.1.19", "body": ["Each hit from this Weapon that inflicts 1 or more damage against a Building inflicts X additional Collateral Damage hits. Each hit that inflicts 1 or more damage against an Area inflicts 2x X additional Collateral Damage hits."]}, "Indirect": {"heading": "Indirect", "number": "11.1.20", "body": ["When attacking with this Weapon, any other friendly Unit may also be used to draw Line of Sight from, in which case it suffers -2Ac. If that friendly Unit has Scout, the -2Ac is ignored.", "For Sited Units with Indirect, no portion of a Building they Occupy can lie between the face they are Sited on and their target."]}, "Ineffective": {"heading": "Ineffective: X", "number": "11.1.21", "body": ["This Weapon cannot damage or affect things of the type X."]}, "Jammer": {"heading": "Jammer", "number": "11.1.22", "body": ["If a Unit is hit by this Weapon, place a Jammed Status Token on its Squad. Weapons with two R values that attack a Jammed Squad may use their 1st value. Jammed Squads, and Units and Weapons within them, cannot be affected by their player’s Command Cards that take effect while the Squad is Jammed."]}, "LX": {"heading": "LX (Limited)", "number": "11.1.23", "body": ["This Weapon may only attack X times/game."]}, "Needs Spotter": {"heading": "Needs Spotter", "number": "11.1.24", "body": ["This Weapon’s target must be in Clear or Obscured Line of Sight of a friendly Unit with Scout, or it suffers -2Ac."]}, "Overcharge": {"heading": "Overcharge X", "number": "11.1.25", "body": ["If its Unit moves 0” (before or after attacking), this Weapon gains +X E that activation."]}, "Overwatch": {"heading": "Overwatch", "number": "11.1.26", "body": ["This Weapon may Reaction Attack against Vehicles and suffers no penalty for doing so. It may only Reaction Attack."]}, "Pen": {"heading": "Pen X+ (Penetrative)", "number": "11.1.27", "body": ["When rolling to inflict damage against Units, this Weapon may always succeed on a roll of X+ regardless of E or A values. This cannot be modified. This can alter the roll required for a Critical—Pen 4+ would inflict a Critical on a 6+."]}, "Precision": {"heading": "Precision X", "number": "11.1.28", "body": ["If its Unit moves 0” (before or after attacking), this Weapon gains +X Ac that activation and if it has Destroyer, it also gains +X Destroyer."]}, "Repair": {"heading": "Repair X/Y", "number": "11.1.29", "body": ["This Weapon may only target Y, and Y may be a friendly Unit. For each hit by this Weapon, the target regains X lost DP."]}, "Seeker": {"heading": "Seeker", "number": "11.1.30", "body": ["This Weapon may target Occupiers as if they were Sited anywhere on a Zone. This Weapon ignores the Ac penalty against Obscured targets if they Occupy the same Zone as friendly Occupiers."]}, "Self-Destruct": {"heading": "Self-Destruct", "number": "11.1.31", "body": ["This uses the same rules as a Field Weapon, except that the attacking Unit is destroyed, and Units within its Squad can be damaged by it.", "If a Unit with a Self-Destruct Weapon is destroyed while not Embarked, roll a D6. On a 4+, the Unit must immediately attack with the Weapon before being removed, even if it could not normally attack."]}, "Smoke": {"heading": "Smoke", "number": "11.1.32", "body": ["If a Squad receives at least as many hits from Weapons with Smoke during a single activation as it has Units, place an Obscured Status Token on that Squad. Squads with Obscured Status Tokens are Obscured.", "This Weapon may target friendly Units and may target its own Unit."]}, "Strafe": {"heading": "Strafe", "number": "11.1.33", "body": ["When attacking during its Unit’s activation, this Weapon may freely split its attacks between Units within 3” of at least one other Unit it targets.. This must be a single chain of targets."]}, "Suppress": {"heading": "Suppress", "number": "11.1.34", "body": ["If a Unit is hit by this Weapon, place a Suppressed Status Token on its Squad. Suppressed Squads may only move 0” if any Unit within it attacks. Suppressed Fast Movers may not attack."]}, "TX": {"heading": "TX (Tracking)", "number": "11.1.35", "body": ["This Weapon reduces the target’s Ev by X to a minimum of 0. For example, T2 would reduce Ev3 to Ev1."]}}};
